/**
 * 🛡️ P1-D（2026-11-17 · mc-max-1794845355582-f3d7f352 实锤）段标题占位名治理
 *
 * 病灶：真值节点 `43:4892` 图层名 = `Frame 2136639911`（Figma 自动编号），vision 直接把它
 *   当段标题输出 ⇒ 产物
 *   `<span class="c-device-fg-header-434892-title" …>Frame 2136639911</span>` 直出到 UI。
 *   真值核对：该段子树只有 3 张统计卡（总设备 8 / 运行中 2 / 离线 1）**本来没有标题**
 *   ⇒ 正确行为是**不渲染段头**，不是渲染英文图层名。
 *
 * 本 spec 锁五件事：
 *   ① `isAutoGeneratedNodeName` 阳性 6 形态（Frame/Rectangle/Group/Vector/Ellipse/Boolean Operation）；
 *   ② 阴性 6 形态 —— 尤其 `Frame标题` / `frame rate` / `Frame 1280 标题` **不得**误杀（可能是真实文案）；
 *   ③ `isNonSemanticName` **行为零变化**（它复用同一常量，但域更宽：`text`/`label` 仍算无语义）；
 *   ④ `pickSectionTitle` 取值顺序：header.title → title → name，逐个跳过占位名；全占位 ⇒ 空串；
 *   ⑤ `sanitizeSectionTitlePlaceholders`：清 header.title 与 title、**不动 name**、幂等、非数组 fail-open。
 */
import { isAutoGeneratedNodeName, isNonSemanticName } from '../utils/decor-leaf-truth.js';
import {
  pickSectionTitle,
  sanitizeSectionTitlePlaceholders,
} from '../utils/section-title-truth.js';

describe('isAutoGeneratedNodeName · 判据', () => {
  it.each([
    'Frame 2136639911',
    'Rectangle 346242326',
    'Group 2136638432',
    'Vector',
    'Ellipse 3',
    'Boolean Operation 1',
    'Frame',
  ])('阳性：%s ⇒ true', (name) => {
    expect(isAutoGeneratedNodeName(name)).toBe(true);
  });

  it.each([
    ['Frame标题', '类型词后直接接中文（真实文案可能长这样）'],
    ['frame rate', '类型词后是英文单词'],
    ['Frame 1280 标题', '类型词+编号后还有中文'],
    ['战略合作厂商', '纯中文业务文案'],
    ['label', '单词语义宽泛，但完全可能是真实 label 文本'],
    ['text', '同上'],
    ['查看更多', '中文动作文案'],
  ])('阴性：%s ⇒ false（%s）', (name) => {
    expect(isAutoGeneratedNodeName(name)).toBe(false);
  });

  it('阴性：空/空白/undefined ⇒ false（不是「占位名」，是「没有值」）', () => {
    expect(isAutoGeneratedNodeName('')).toBe(false);
    expect(isAutoGeneratedNodeName('   ')).toBe(false);
    expect(isAutoGeneratedNodeName(undefined)).toBe(false);
    expect(isAutoGeneratedNodeName(null)).toBe(false);
  });
});

describe('isNonSemanticName · 复用同一常量后的行为零变化', () => {
  it('回归锚：自动编号仍判无语义（原内联正则与本常量逐字相同）', () => {
    expect(isNonSemanticName('Frame 1280')).toBe(true);
    expect(isNonSemanticName('Group 2136638523')).toBe(true);
  });

  it('回归锚：节点名域**更宽** —— text / label 仍算无语义（本改动的窄判据不得反向影响它）', () => {
    expect(isNonSemanticName('text')).toBe(true);
    expect(isNonSemanticName('label')).toBe(true);
    expect(isNonSemanticName('btn')).toBe(true);
  });

  it('回归锚：`g-xxx` 判无语义 —— **既有行为**（`\\b` 在 `g` 与 `-` 之间成立，第二档命中）', () => {
    // ⚠️ 本断言按**实测**写，不按注释推断：`isResourceWrapperName` 才有「精确匹配 g、避免误伤 g-xxx」
    //   那条边界，`isNonSemanticName` 没有 —— 后者第二档 `/^(bg|icon|…|g|…)\b/i` 对 `g-xxx` 命中。
    //   本次改动只把**第一档**（自动编号）换成常量，第二档逐字未动 ⇒ 此值必须与改前一致。
    expect(isNonSemanticName('g-xxx')).toBe(true);
  });
});

describe('pickSectionTitle · 取值唯一口径', () => {
  it('阳性：header.title 是真值文案 ⇒ 直接取', () => {
    expect(pickSectionTitle({ header: { title: '战略合作厂商' }, title: '别的', name: 'Group 1' })).toBe(
      '战略合作厂商',
    );
  });

  it('阳性：header.title 是占位名 ⇒ 退到 title', () => {
    expect(pickSectionTitle({ header: { title: 'Frame 2136639911' }, title: '设备总览', name: 'X' })).toBe(
      '设备总览',
    );
  });

  it('阳性：header.title 与 title 都是占位名 ⇒ 退到 name（若 name 非占位）', () => {
    expect(
      pickSectionTitle({ header: { title: 'Frame 1' }, title: 'Rectangle 2', name: '在线设备' }),
    ).toBe('在线设备');
  });

  it('阴性：三者全占位/空 ⇒ 空串（下游见空标题即不渲染段头）', () => {
    expect(pickSectionTitle({ header: { title: 'Frame 2136639911' }, title: '', name: 'Group 9' })).toBe('');
    expect(pickSectionTitle({})).toBe('');
    expect(pickSectionTitle(null)).toBe('');
  });

  it('阴性：不把 `label` / `text` 当占位名清掉（与 isNonSemanticName 的关键分野）', () => {
    expect(pickSectionTitle({ header: { title: 'label' } })).toBe('label');
  });
});

describe('sanitizeSectionTitlePlaceholders · 就地净化', () => {
  it('阳性：本单形态（header.title + title 同为占位名）⇒ 两字段清空，name 原样保留', () => {
    const secs: any[] = [
      { id: '43:4892', title: 'Frame 2136639911', header: { title: 'Frame 2136639911' }, name: 'Frame 2136639911' },
    ];
    const stats = sanitizeSectionTitlePlaceholders(secs);
    expect(stats).toMatchObject({ evaluated: 1, cleared: 1, clearedIds: ['43:4892'], clearedValues: ['Frame 2136639911'] });
    expect(secs[0].header.title).toBe('');
    expect(secs[0].title).toBe('');
    // 🔴 name 是节点名：下游按 name 匹配 Figma 节点，**必须原样保留**
    expect(secs[0].name).toBe('Frame 2136639911');
  });

  it('阴性：真值标题不动（如 `具身机器人设备列表`）', () => {
    const secs: any[] = [{ id: '43:4879', title: '具身机器人设备列表', header: { title: '具身机器人设备列表' } }];
    const stats = sanitizeSectionTitlePlaceholders(secs);
    expect(stats).toMatchObject({ evaluated: 1, cleared: 0 });
    expect(secs[0].header.title).toBe('具身机器人设备列表');
    expect(secs[0].title).toBe('具身机器人设备列表');
  });

  it('幂等：连跑两次，第二次 cleared=0 且值不变', () => {
    const secs: any[] = [{ id: 'a', title: 'Frame 1', header: { title: 'Frame 1' } }];
    sanitizeSectionTitlePlaceholders(secs);
    const again = sanitizeSectionTitlePlaceholders(secs);
    expect(again).toMatchObject({ evaluated: 1, cleared: 0 });
    expect(secs[0].header.title).toBe('');
  });

  it('fail-open：非数组 ⇒ 零计数、不抛', () => {
    expect(sanitizeSectionTitlePlaceholders(undefined as any)).toMatchObject({ evaluated: 0, cleared: 0 });
    expect(sanitizeSectionTitlePlaceholders({} as any)).toMatchObject({ evaluated: 0, cleared: 0 });
  });

  it('稳健：header 为 null / 非对象时只清 title，不抛', () => {
    const secs: any[] = [{ id: 'b', title: 'Rectangle 26', header: null }];
    const stats = sanitizeSectionTitlePlaceholders(secs);
    expect(stats).toMatchObject({ evaluated: 1, cleared: 1 });
    expect(secs[0].title).toBe('');
  });
});
